onTurnStart.script:
// === Curse MP-Drain v1 (Effect Macro → On Combat Turn Starting) ============
// Drains % Max MP using your Advance Damage macro, *without* UI targeting.
//
// • Default: 20% of max MP
// • Champion rank (NPC): 10%
// • PCs / no rank field: 20%
// • Value type: "mp", Weapon type: "none_ef" (neutral), Element can be anything (not used for MP SFX)
//
// Requires: AdvanceDamage supports headless targets via __PAYLOAD.targetIds.
// ===========================================================================

(async () => {
  const ADV_DMG_MACRO_NAME = "AdvanceDamage"; // rename if your macro differs

  // --- Only act on the owner’s actual turn ---------------------------------
  if (!actor || !game.combat) return;
  const isOwnersTurn = game.combat?.combatant?.actor?.id === actor.id;
  if (!isOwnersTurn) return;

  // --- Resolve the correct token id for this actor on this turn ------------
  function pickTokenIdForActor(a) {
    const ct = game.combat?.combatant;
    if (ct?.actor?.id === a.id && ct.token?.id) return ct.token.id;
    if (token?.id) return token.id;
    const t = a.getActiveTokens()?.[0];
    return t?.id ?? t?.document?.id ?? null;
  }
  const tokenId = pickTokenIdForActor(actor);
  if (!tokenId) return ui.notifications.warn("[Curse] No active token for effect owner.");

  // --- Determine % by NPC Rank (Champion halves it) ------------------------
  // NPC sheet has system.props.npc_rank with options including "cha" (Champion).
  const props = actor.system?.props ?? {};
  const rank  = String(props.npc_rank ?? "").toLowerCase(); // e.g., "cha"
  const percent = (rank === "cha") ? 10 : 20;  // PCs / missing field → 20%

  // --- Build headless payload for AdvanceDamage ----------------------------
  const payload = {
    baseValue: String(percent),    // just the number, no '%' sign
    valueType: "mp",               // drain MP
    targetAffinity: "percentMax",  // % of target's max MP
    elementType: "dark",           // thematic; MP SFX is driven by valueType anyway
    weaponType: "none_ef",
    ignoreDamageReduction: true,   // MP isn’t reduced by armor; set false if you prefer
    ignoreShield: true,            // shields shouldn’t block MP drain

    // Context strings for your logs/cards
    attackerName: "Curse",
    attackRange: "DOT",
    sourceType : "Effect: Curse",

    // Headless targets (prevents Foundry crosshair flashing)
    targetIds: [tokenId]
  };

  const ADV = game.macros.getName(ADV_DMG_MACRO_NAME);
  if (!ADV) return ui.notifications.error(`[Curse] Macro "${ADV_DMG_MACRO_NAME}" not found.`);

  await ADV.execute({ __AUTO: true, __PAYLOAD: payload });
})();
